-- Sharawla POS — Logistics Engine V1
begin;
create table if not exists public.logistics_zones_v1(id bigserial primary key,code text unique,name text not null,base_fee numeric(14,2) not null default 0,extra_kg_fee numeric(14,2) not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.logistics_drivers_v1(id bigserial primary key,employee_id bigint unique references public.employees(id) on delete set null,name text not null,phone text,vehicle text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.logistics_shipments_v1(id bigserial primary key,tracking_number text unique,branch_id bigint not null references public.branches(id),client_customer_id bigint references public.customers(id),recipient_name text not null,recipient_phone text not null,recipient_address text not null,origin_zone_id bigint references public.logistics_zones_v1(id),destination_zone_id bigint references public.logistics_zones_v1(id),weight_kg numeric(14,3) not null default 0 check(weight_kg>=0),shipping_fee numeric(14,2) not null default 0,cod_amount numeric(14,2) not null default 0 check(cod_amount>=0),status text not null default 'created' check(status in('created','pickup_requested','picked_up','at_hub','out_for_delivery','delivered','delivery_failed','returning','returned','cancelled')),driver_id bigint references public.logistics_drivers_v1(id) on delete set null,reference text,notes text,client_tx_id text not null unique,created_by_employee_id bigint references public.employees(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),delivered_at timestamptz);
create index if not exists logistics_shipments_branch_status_idx on public.logistics_shipments_v1(branch_id,status,created_at desc);create index if not exists logistics_shipments_client_idx on public.logistics_shipments_v1(client_customer_id,created_at desc);
create table if not exists public.logistics_tracking_events_v1(id bigserial primary key,shipment_id bigint not null references public.logistics_shipments_v1(id) on delete cascade,status text not null,location text,note text,driver_id bigint references public.logistics_drivers_v1(id),employee_id bigint references public.employees(id),created_at timestamptz not null default now());
create table if not exists public.logistics_waybills_v1(id bigserial primary key,shipment_id bigint not null unique references public.logistics_shipments_v1(id) on delete cascade,waybill_number text not null unique,barcode text unique,generated_at timestamptz not null default now());
create table if not exists public.logistics_pickup_requests_v1(id bigserial primary key,branch_id bigint not null references public.branches(id),client_customer_id bigint references public.customers(id),pickup_address text not null,contact_name text,contact_phone text,requested_at timestamptz not null default now(),scheduled_at timestamptz,status text not null default 'requested' check(status in('requested','assigned','picked_up','cancelled')),driver_id bigint references public.logistics_drivers_v1(id),notes text,client_tx_id text not null unique);
create table if not exists public.logistics_cod_events_v1(id bigserial primary key,shipment_id bigint not null references public.logistics_shipments_v1(id),event_type text not null check(event_type in('collected','refunded','settled')),amount numeric(14,2) not null check(amount>0),method text,reference text,employee_id bigint references public.employees(id),client_tx_id text not null unique,created_at timestamptz not null default now());
create table if not exists public.logistics_client_settlements_v1(id bigserial primary key,branch_id bigint not null references public.branches(id),client_customer_id bigint not null references public.customers(id),settlement_number text unique,period_from date,period_to date,status text not null default 'draft' check(status in('draft','approved','paid','cancelled')),gross_cod numeric(14,2) not null default 0,shipping_fees numeric(14,2) not null default 0,other_deductions numeric(14,2) not null default 0,net_payable numeric(14,2) not null default 0,client_tx_id text not null unique,created_by_employee_id bigint references public.employees(id),created_at timestamptz not null default now(),paid_at timestamptz);
create table if not exists public.logistics_client_settlement_items_v1(id bigserial primary key,settlement_id bigint not null references public.logistics_client_settlements_v1(id) on delete cascade,shipment_id bigint not null references public.logistics_shipments_v1(id),cod_amount numeric(14,2) not null default 0,shipping_fee numeric(14,2) not null default 0,net_amount numeric(14,2) not null default 0,unique(settlement_id,shipment_id));
create table if not exists public.logistics_returns_v1(id bigserial primary key,shipment_id bigint not null unique references public.logistics_shipments_v1(id),reason text,status text not null default 'requested' check(status in('requested','in_transit','returned','cancelled')),return_fee numeric(14,2) not null default 0,created_at timestamptz not null default now(),completed_at timestamptz);

create or replace function public.logistics_quote_v1(p_zone_id bigint,p_weight_kg numeric) returns numeric language sql stable security definer set search_path=public as $$select round(base_fee+greatest(coalesce(p_weight_kg,0)-1,0)*extra_kg_fee,2) from public.logistics_zones_v1 where id=p_zone_id and active=true$$;
create or replace function public.logistics_shipment_create_v1(p_branch_id bigint,p_client_customer_id bigint,p_recipient_name text,p_recipient_phone text,p_recipient_address text,p_origin_zone_id bigint,p_destination_zone_id bigint,p_weight_kg numeric,p_cod_amount numeric,p_reference text,p_notes text,p_client_tx_id text)
returns bigint language plpgsql security definer set search_path=public as $$declare idv bigint;k text:=nullif(trim(coalesce(p_client_tx_id,'')),'');e bigint;fee numeric:=0;begin if auth.uid() is null then raise exception 'غير مصرح';end if;if not public.has_branch_access(p_branch_id) then raise exception 'ليس لديك صلاحية لهذا الفرع';end if;if k is null then raise exception 'معرف الحركة مطلوب';end if;if nullif(trim(coalesce(p_recipient_name,'')),'') is null or nullif(trim(coalesce(p_recipient_phone,'')),'') is null or nullif(trim(coalesce(p_recipient_address,'')),'') is null then raise exception 'بيانات المستلم مطلوبة';end if;perform pg_advisory_xact_lock(hashtextextended('shipment:'||k,0));select id into idv from public.logistics_shipments_v1 where client_tx_id=k;if idv is not null then return idv;end if;fee:=coalesce(public.logistics_quote_v1(p_destination_zone_id,p_weight_kg),0);e:=public.current_employee_id();insert into public.logistics_shipments_v1(branch_id,client_customer_id,recipient_name,recipient_phone,recipient_address,origin_zone_id,destination_zone_id,weight_kg,shipping_fee,cod_amount,reference,notes,client_tx_id,created_by_employee_id) values(p_branch_id,p_client_customer_id,trim(p_recipient_name),trim(p_recipient_phone),trim(p_recipient_address),p_origin_zone_id,p_destination_zone_id,greatest(coalesce(p_weight_kg,0),0),fee,greatest(coalesce(p_cod_amount,0),0),nullif(trim(coalesce(p_reference,'')),''),nullif(trim(coalesce(p_notes,'')),''),k,e) returning id into idv;update public.logistics_shipments_v1 set tracking_number='SH-'||to_char(current_date,'YYMMDD')||'-'||lpad(idv::text,7,'0') where id=idv;insert into public.logistics_tracking_events_v1(shipment_id,status,note,employee_id) values(idv,'created','Shipment created',e);insert into public.logistics_waybills_v1(shipment_id,waybill_number,barcode) values(idv,'WB-'||lpad(idv::text,10,'0'),'WB'||lpad(idv::text,12,'0'));return idv;end;$$;
create or replace function public.logistics_shipment_status_v1(p_shipment_id bigint,p_status text,p_location text,p_note text,p_driver_id bigint)
returns public.logistics_shipments_v1 language plpgsql security definer set search_path=public as $$declare r public.logistics_shipments_v1%rowtype;e bigint;begin if auth.uid() is null then raise exception 'غير مصرح';end if;select * into r from public.logistics_shipments_v1 where id=p_shipment_id for update;if not found or not public.has_branch_access(r.branch_id) then raise exception 'الشحنة غير موجودة أو غير مصرح';end if;if p_status not in('created','pickup_requested','picked_up','at_hub','out_for_delivery','delivered','delivery_failed','returning','returned','cancelled') then raise exception 'حالة غير صحيحة';end if;e:=public.current_employee_id();update public.logistics_shipments_v1 set status=p_status,driver_id=coalesce(p_driver_id,driver_id),delivered_at=case when p_status='delivered' then coalesce(delivered_at,now()) else delivered_at end,updated_at=now() where id=r.id returning * into r;insert into public.logistics_tracking_events_v1(shipment_id,status,location,note,driver_id,employee_id) values(r.id,p_status,nullif(trim(coalesce(p_location,'')),''),nullif(trim(coalesce(p_note,'')),''),p_driver_id,e);return r;end;$$;
create or replace function public.logistics_cod_collect_v1(p_shipment_id bigint,p_amount numeric,p_method text,p_reference text,p_client_tx_id text)
returns bigint language plpgsql security definer set search_path=public as $$declare s public.logistics_shipments_v1%rowtype;idv bigint;e bigint;k text:=nullif(trim(coalesce(p_client_tx_id,'')),'');col numeric;begin if auth.uid() is null then raise exception 'غير مصرح';end if;if k is null then raise exception 'معرف الحركة مطلوب';end if;perform pg_advisory_xact_lock(hashtextextended('cod:'||k,0));select id into idv from public.logistics_cod_events_v1 where client_tx_id=k;if idv is not null then return idv;end if;select * into s from public.logistics_shipments_v1 where id=p_shipment_id;if not found or not public.has_branch_access(s.branch_id) then raise exception 'الشحنة غير موجودة أو غير مصرح';end if;select coalesce(sum(case when event_type='collected' then amount when event_type in('refunded','settled') then -amount else 0 end),0) into col from public.logistics_cod_events_v1 where shipment_id=s.id;if coalesce(p_amount,0)<=0 or col+p_amount>s.cod_amount+0.01 then raise exception 'قيمة COD غير صحيحة';end if;e:=public.current_employee_id();insert into public.logistics_cod_events_v1(shipment_id,event_type,amount,method,reference,employee_id,client_tx_id) values(s.id,'collected',round(p_amount,2),nullif(trim(coalesce(p_method,'')),''),nullif(trim(coalesce(p_reference,'')),''),e,k) returning id into idv;return idv;end;$$;
create or replace function public.logistics_pickup_request_create_v1(p_branch_id bigint,p_client_customer_id bigint,p_address text,p_contact_name text,p_contact_phone text,p_scheduled_at timestamptz,p_notes text,p_client_tx_id text)
returns bigint language plpgsql security definer set search_path=public as $$declare idv bigint;k text:=nullif(trim(coalesce(p_client_tx_id,'')),'');begin if auth.uid() is null then raise exception 'غير مصرح';end if;if not public.has_branch_access(p_branch_id) then raise exception 'ليس لديك صلاحية لهذا الفرع';end if;if k is null then raise exception 'معرف الحركة مطلوب';end if;perform pg_advisory_xact_lock(hashtextextended('pickup:'||k,0));select id into idv from public.logistics_pickup_requests_v1 where client_tx_id=k;if idv is not null then return idv;end if;insert into public.logistics_pickup_requests_v1(branch_id,client_customer_id,pickup_address,contact_name,contact_phone,scheduled_at,notes,client_tx_id) values(p_branch_id,p_client_customer_id,trim(p_address),nullif(trim(coalesce(p_contact_name,'')),''),nullif(trim(coalesce(p_contact_phone,'')),''),p_scheduled_at,nullif(trim(coalesce(p_notes,'')),''),k) returning id into idv;return idv;end;$$;
create or replace function public.logistics_settlement_create_v1(p_branch_id bigint,p_client_customer_id bigint,p_period_from date,p_period_to date,p_client_tx_id text)
returns bigint language plpgsql security definer set search_path=public as $$declare idv bigint;k text:=nullif(trim(coalesce(p_client_tx_id,'')),'');e bigint;g numeric:=0;fees numeric:=0;begin if auth.uid() is null or not public.is_admin() then raise exception 'التسويات للمدير فقط';end if;if not public.has_branch_access(p_branch_id) then raise exception 'ليس لديك صلاحية لهذا الفرع';end if;if k is null then raise exception 'معرف الحركة مطلوب';end if;perform pg_advisory_xact_lock(hashtextextended('settlement:'||k,0));select id into idv from public.logistics_client_settlements_v1 where client_tx_id=k;if idv is not null then return idv;end if;e:=public.current_employee_id();select coalesce(sum(s.cod_amount),0),coalesce(sum(s.shipping_fee),0) into g,fees from public.logistics_shipments_v1 s where s.branch_id=p_branch_id and s.client_customer_id=p_client_customer_id and s.status='delivered' and date(s.delivered_at) between p_period_from and p_period_to and not exists(select 1 from public.logistics_client_settlement_items_v1 i where i.shipment_id=s.id);insert into public.logistics_client_settlements_v1(branch_id,client_customer_id,period_from,period_to,gross_cod,shipping_fees,net_payable,client_tx_id,created_by_employee_id) values(p_branch_id,p_client_customer_id,p_period_from,p_period_to,g,fees,g-fees,k,e) returning id into idv;insert into public.logistics_client_settlement_items_v1(settlement_id,shipment_id,cod_amount,shipping_fee,net_amount) select idv,s.id,s.cod_amount,s.shipping_fee,s.cod_amount-s.shipping_fee from public.logistics_shipments_v1 s where s.branch_id=p_branch_id and s.client_customer_id=p_client_customer_id and s.status='delivered' and date(s.delivered_at) between p_period_from and p_period_to and not exists(select 1 from public.logistics_client_settlement_items_v1 i where i.shipment_id=s.id);update public.logistics_client_settlements_v1 set settlement_number='SET-'||to_char(current_date,'YYMM')||'-'||lpad(idv::text,6,'0') where id=idv;return idv;end;$$;
create or replace function public.logistics_return_create_v1(p_shipment_id bigint,p_reason text,p_return_fee numeric)
returns bigint language plpgsql security definer set search_path=public as $$declare s public.logistics_shipments_v1%rowtype;idv bigint;begin if auth.uid() is null then raise exception 'غير مصرح';end if;select * into s from public.logistics_shipments_v1 where id=p_shipment_id for update;if not found or not public.has_branch_access(s.branch_id) then raise exception 'الشحنة غير موجودة أو غير مصرح';end if;insert into public.logistics_returns_v1(shipment_id,reason,return_fee) values(s.id,nullif(trim(coalesce(p_reason,'')),''),greatest(coalesce(p_return_fee,0),0)) on conflict(shipment_id) do update set reason=excluded.reason,return_fee=excluded.return_fee returning id into idv;update public.logistics_shipments_v1 set status='returning',updated_at=now() where id=s.id;return idv;end;$$;

alter table public.logistics_zones_v1 enable row level security;alter table public.logistics_drivers_v1 enable row level security;alter table public.logistics_shipments_v1 enable row level security;alter table public.logistics_tracking_events_v1 enable row level security;alter table public.logistics_waybills_v1 enable row level security;alter table public.logistics_pickup_requests_v1 enable row level security;alter table public.logistics_cod_events_v1 enable row level security;alter table public.logistics_client_settlements_v1 enable row level security;alter table public.logistics_client_settlement_items_v1 enable row level security;alter table public.logistics_returns_v1 enable row level security;
create policy logistics_zones_read_v1 on public.logistics_zones_v1 for select to authenticated using(active=true);create policy logistics_drivers_read_v1 on public.logistics_drivers_v1 for select to authenticated using(active=true);create policy logistics_shipments_read_v1 on public.logistics_shipments_v1 for select to authenticated using(public.has_branch_access(branch_id));create policy logistics_tracking_read_v1 on public.logistics_tracking_events_v1 for select to authenticated using(exists(select 1 from public.logistics_shipments_v1 s where s.id=shipment_id and public.has_branch_access(s.branch_id)));create policy logistics_waybills_read_v1 on public.logistics_waybills_v1 for select to authenticated using(exists(select 1 from public.logistics_shipments_v1 s where s.id=shipment_id and public.has_branch_access(s.branch_id)));create policy logistics_pickups_read_v1 on public.logistics_pickup_requests_v1 for select to authenticated using(public.has_branch_access(branch_id));create policy logistics_cod_read_v1 on public.logistics_cod_events_v1 for select to authenticated using(exists(select 1 from public.logistics_shipments_v1 s where s.id=shipment_id and public.has_branch_access(s.branch_id)));create policy logistics_settlements_read_v1 on public.logistics_client_settlements_v1 for select to authenticated using(public.has_branch_access(branch_id));create policy logistics_settlement_items_read_v1 on public.logistics_client_settlement_items_v1 for select to authenticated using(exists(select 1 from public.logistics_client_settlements_v1 s where s.id=settlement_id and public.has_branch_access(s.branch_id)));create policy logistics_returns_read_v1 on public.logistics_returns_v1 for select to authenticated using(exists(select 1 from public.logistics_shipments_v1 s where s.id=shipment_id and public.has_branch_access(s.branch_id)));
grant select on public.logistics_zones_v1,public.logistics_drivers_v1,public.logistics_shipments_v1,public.logistics_tracking_events_v1,public.logistics_waybills_v1,public.logistics_pickup_requests_v1,public.logistics_cod_events_v1,public.logistics_client_settlements_v1,public.logistics_client_settlement_items_v1,public.logistics_returns_v1 to authenticated;
grant execute on function public.logistics_quote_v1(bigint,numeric) to authenticated;grant execute on function public.logistics_shipment_create_v1(bigint,bigint,text,text,text,bigint,bigint,numeric,numeric,text,text,text) to authenticated;grant execute on function public.logistics_shipment_status_v1(bigint,text,text,text,bigint) to authenticated;grant execute on function public.logistics_cod_collect_v1(bigint,numeric,text,text,text) to authenticated;grant execute on function public.logistics_pickup_request_create_v1(bigint,bigint,text,text,text,timestamptz,text,text) to authenticated;grant execute on function public.logistics_settlement_create_v1(bigint,bigint,date,date,text) to authenticated;grant execute on function public.logistics_return_create_v1(bigint,text,numeric) to authenticated;
commit;
